3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"log/slog"
9		"os"
10		"os/exec"
11		"strings"
12		"sync"
13		"time"
14	
15		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
16		"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
17		"github.com/entireio/cli/cmd/entire/cli/logging"
18		"github.com/entireio/cli/cmd/entire/cli/paths"
19		"github.com/entireio/cli/cmd/entire/cli/settings"
20	
21		"github.com/go-git/go-git/v6"
22		"github.com/go-git/go-git/v6/plumbing"
23		"github.com/go-git/go-git/v6/plumbing/object"
24	)
25	
26	// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
27	// The target can be a remote name (e.g., "origin") or a URL for direct push.
28	// When pushing to a URL, the "has unpushed" optimization is skipped since there are
29	// no remote tracking refs — git itself handles the no-op case.
30	// Does not check any settings — callers are responsible for gating.
31	func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
32		repo, err := OpenRepository(ctx)
33		if err != nil {
34			return nil //nolint:nilerr // Hook must be silent on failure
35		}
36	
37		// Check if branch exists locally
38		branchRef := plumbing.NewBranchReferenceName(branchName)
39		localRef, err := repo.Reference(branchRef, true)
40		if err != nil {
41			// No branch, nothing to push
42			return nil //nolint:nilerr // Expected when no sessions exist yet
43		}
44	
45		// Only check remote tracking refs when target is a remote name (not a URL).
46		// URLs don't have tracking refs, so we always attempt the push and let git handle it.
47		if !remote.IsURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
48			return nil
49		}
50	
51		return doPushBranch(ctx, target, branchName)
52	}
53	
54	// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
55	// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
56	func hasUnpushedSessionsCommon(repo *git.Repository, remoteName string, localHash plumbing.Hash, branchName string) bool {
57		// Check for remote tracking ref: refs/remotes/<remoteName>/<branch>
58		remoteRefName := plumbing.NewRemoteReferenceName(remoteName, branchName)
59		remoteRef, err := repo.Reference(remoteRefName, true)
60		if err != nil {
61			// Remote branch doesn't exist yet - we have content to push
62			return true
63		}
64	
65		// If local and remote point to same commit, nothing to sync
66		// This is the only case where we skip - any difference needs handling
67		return localHash != remoteRef.Hash()
68	}
69	
70	func displayPushTarget(target string) string {
71		if remote.IsURL(target) {
72			return "checkpoint remote"
73		}
74		return target
75	}
76	
77	// doPushBranch pushes the given branch to the target with fetch+merge recovery.
78	// The target can be a remote name or a URL.
79	func doPushBranch(ctx context.Context, target, branchName string) error {
80		displayTarget := displayPushTarget(target)
81	
82		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
83		stop := startProgressDots(os.Stderr)
84	
85		// Try pushing first
86		result, err := tryPushSessionsCommon(ctx, target, branchName)
87		if err == nil {
88			finishPush(ctx, stop, result, target)
89			return nil
90		}
91		stop("")
92	
93		// Protected refs cannot be fixed by syncing and retrying.
94		var protectedErr *protectedRefError
95		if errors.As(err, &protectedErr) {
96			printProtectedRefBlock(os.Stderr, branchName, target)
97			return nil
98		}
99	
100		// Push failed - likely non-fast-forward. Try to fetch and rebase.
101		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
102		stop = startProgressDots(os.Stderr)
103	
104		if err := fetchAndRebaseSessionsCommon(ctx, target, branchName); err != nil {
105			stop("")
106			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, err)
107			printCheckpointRemoteHint(target)
108			return nil // Don't fail the main push
109		}
110		stop(" done")
111	
112		// Try pushing again after rebase
113		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
114		stop = startProgressDots(os.Stderr)
115	
116		if result, err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
117			stop("")
118			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
119			printCheckpointRemoteHint(target)
120		} else {
121			finishPush(ctx, stop, result, target)
122		}
123	
124		return nil
125	}
126	
127	// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
128	// Only prints when the target is a URL (not the user's default remote).
129	func printCheckpointRemoteHint(target string) {
130		if !remote.IsURL(target) {
131			return
132		}
133		fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
134		fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
135	}
136	
137	// settingsHintOnce ensures the settings commit hint prints at most once per process.
138	var settingsHintOnce sync.Once
139	
140	// checkpointsV2MigrationHintOnce ensures the checkpoints v2 migration hint prints at most once per process.
141	var checkpointsV2MigrationHintOnce sync.Once
142	
143	// printSettingsCommitHint prints a hint after a successful checkpoint remote push
144	// when the committed .entire/settings.json does not contain a checkpoint_remote config.
145	// entire.io discovers the external checkpoint repo by reading the committed project
146	// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
147	// (not just in settings.local.json or uncommitted local changes).
148	// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
149	// single pre-push invocation.
150	func printSettingsCommitHint(ctx context.Context, target string) {
151		if !remote.IsURL(target) {
152			return
153		}
154		settingsHintOnce.Do(func() {
155			if isCheckpointRemoteCommitted(ctx) {
156				return
157			}
158			fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
159		})
160	}
161	
162	// printCheckpointsV2MigrationHint nudges users who committed checkpoints_version: 2
163	// but never ran the migration. Partial migrations are not flagged.
164	func printCheckpointsV2MigrationHint(ctx context.Context) {
165		checkpointsV2MigrationHintOnce.Do(func() {
166			if !isCheckpointsVersion2Committed(ctx) {
167				return
168			}
169			if v2MainRefExists(ctx) {
170				return
171			}
172			fmt.Fprintln(os.Stderr, "[entire] Note: .entire/settings.json sets checkpoints_version: 2, but no v2 /main ref was found in this repo.")
173			fmt.Fprintln(os.Stderr, "[entire] Run 'entire migrate --checkpoints v2' to migrate missing checkpoints to v2.")
174		})
175	}
176	
177	func v2MainRefExists(ctx context.Context) bool {
178		repo, err := OpenRepository(ctx)
179		if err != nil {
180			return false
181		}
182		_, err = repo.Reference(plumbing.ReferenceName(paths.V2MainRefName), true)
183		return err == nil
184	}
185	
186	// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
187	// at HEAD contains a valid checkpoint_remote configuration. This is the true
188	// discoverability check: entire.io reads from committed project settings, not from
189	// local overrides or uncommitted changes.
190	func isCheckpointRemoteCommitted(ctx context.Context) bool {
191		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
192		output, err := cmd.Output()
193		if err != nil {
194			return false // file doesn't exist at HEAD
195		}
196		// Parse the committed content and check for checkpoint_remote
197		committed, err := settings.LoadFromBytes(output)
198		if err != nil {
199			return false
200		}
201		return committed.GetCheckpointRemote() != nil
202	}
203	
204	// isCheckpointsVersion2Committed returns true if the committed .entire/settings.json
205	// at HEAD sets checkpoints_version to 2.
206	func isCheckpointsVersion2Committed(ctx context.Context) bool {
207		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
208		output, err := cmd.Output()
209		if err != nil {
210			return false
211		}
212		committed, err := settings.LoadFromBytes(output)
213		if err != nil {
214			return false
215		}
216		return committed.CheckpointsVersion() == 2
217	}
218	
219	// pushResult describes what happened during a push attempt.
220	type pushResult struct {
221		// upToDate is true when the remote already had all commits (nothing transferred).
222		upToDate bool
223	}
224	
225	// parsePushResult checks git push --porcelain output for ref status flags.
226	// In porcelain mode, each ref gets a tab-delimited status line:
227	//
228	//	<flag>\t<from>:<to>\t<summary>
229	//
230	// where flag '=' means the ref was already up-to-date. This is locale-independent,
231	// unlike the human-readable "Everything up-to-date" message.
232	func parsePushResult(output string) pushResult {
233		for _, line := range strings.Split(output, "\n") {
234			if strings.HasPrefix(line, "=\t") {
235				return pushResult{upToDate: true}
236			}
237		}
238		return pushResult{upToDate: false}
239	}
240	
241	// finishPush stops the progress dots and prints "already up-to-date" or "done"
242	// depending on the push result. Only prints the settings commit hint when new
243	// content was actually pushed.
244	func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
245		if result.upToDate {
246			stop(" already up-to-date")
247		} else {
248			stop(" done")
249			printSettingsCommitHint(ctx, target)
250		}
251		printCheckpointsV2MigrationHint(ctx)
252	}
253	
254	// tryPushSessionsCommon attempts to push the sessions branch.
255	func tryPushSessionsCommon(ctx context.Context, remoteName, branchName string) (pushResult, error) {
256		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
257		defer cancel()
258	
259		result, err := remote.Push(ctx, remoteName, branchName)
260		outputStr := result.Output
261		if err != nil {
262			return pushResult{}, classifyPushFailure(ctx, outputStr, err)
263		}
264	
265		return parsePushResult(outputStr), nil
266	}
267	
268	// protectedRefError means the remote is blocking writes to the ref itself.
269	type protectedRefError struct {
270		output string
271	}
272	
273	func (e *protectedRefError) Error() string {
274		return "remote rejected push to protected ref"
275	}
276	
277	// isProtectedRefRejection detects GitHub ruleset and branch-protection failures.
278	func isProtectedRefRejection(output string) bool {
279		return strings.Contains(output, "GH013") ||
280			strings.Contains(output, "Cannot update this protected ref") ||
281			strings.Contains(output, "protected branch hook declined")
282	}
283	
284	var errNonFastForward = errors.New("non-fast-forward")
285	
286	func isNonFastForwardRejection(output string) bool {
287		if strings.Contains(output, "non-fast-forward") {
288			return true
289		}
290		for _, line := range strings.Split(output, "\n") {
291			if strings.Contains(line, "[rejected]") && strings.Contains(line, "(fetch first)") {
292				return true
293			}
294		}
295		return strings.Contains(output, "Updates were rejected because the tip of your current branch is behind") ||
296			strings.Contains(output, "Updates were rejected because the remote contains work that you do not have locally")
297	}
298	
299	// classifyPushOutput maps failing push stderr to a typed error.
300	func classifyPushOutput(output string) error {
301		if isProtectedRefRejection(output) {
302			return &protectedRefError{output: output}
303		}
304		if isNonFastForwardRejection(output) {
305			return errNonFastForward
306		}
307		if strings.TrimSpace(output) == "" {
308			return errors.New("push failed")
309		}
310		return fmt.Errorf("push failed: %s", output)
311	}
312	
313	func classifyPushFailure(ctx context.Context, output string, pushErr error) error {
314		if strings.TrimSpace(output) != "" {
315			if pushErr != nil {
316				logging.Debug(ctx, "git push failed",
317					slog.String("error", pushErr.Error()),
318					slog.String("output", output),
319				)
320			}
321			return classifyPushOutput(output)
322		}
323		if pushErr != nil {
324			logging.Debug(ctx, "git push failed without output",
325				slog.String("error", pushErr.Error()),
326			)
327			return fmt.Errorf("push failed: %w", pushErr)
328		}
329		return errors.New("push failed")
330	}
331	
332	// printProtectedRefBlock explains that checkpoint syncing was blocked remotely.
333	func printProtectedRefBlock(w io.Writer, ref, target string) {
334		const banner = "[entire] ============================================================"
335		displayTarget := displayPushTarget(target)
336		fmt.Fprintln(w, banner)
337		fmt.Fprintf(w, "[entire] BLOCKED: remote rejected push to %s\n", ref)
338		fmt.Fprintln(w, "[entire] Reason:  GitHub branch protection or repository ruleset (e.g. GH013)")
339		fmt.Fprintf(w, "[entire] Target:  %s\n", displayTarget)
340		fmt.Fprintln(w, "[entire] Impact:  checkpoints are saved locally but NOT synced to this remote.")
341		fmt.Fprintln(w, "[entire] Action:  allow pushes to `entire/*` in your ruleset, or set")
342		fmt.Fprintln(w, "[entire]          `checkpoint_remote` in .entire/settings.json to a separate repo.")
343		fmt.Fprintln(w, banner)
344	}
345	
346	// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
347	// on top of the remote tip. Since checkpoint shards use unique paths, rebases
348	// always apply cleanly.
349	// The target can be a remote name or a URL.
350	func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
351		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
352		defer cancel()
353	
354		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
355		if err != nil {
356			return fmt.Errorf("resolve fetch target: %w", err)
357		}
358	
359		// Determine fetch refspec. When the resolved fetch target is a URL, use a
360		// temp ref; when it's still a remote name, use the standard remote-tracking
361		// ref.
362		var fetchedRefName plumbing.ReferenceName
363		var refSpec string
364		usedTempRef := remote.IsURL(fetchTarget)
365		if usedTempRef {
366			tmpRef := "refs/entire-fetch-tmp/" + branchName
367			refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
368			fetchedRefName = plumbing.ReferenceName(tmpRef)
369		} else {
370			refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
371			fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
372		}
373	
374		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
375		// Use --filter=blob:none for a partial fetch that downloads only commits
376		// and trees, skipping blobs. The merge only needs the tree structure to
377		// combine entries; blobs are already local or fetched on demand.
378		if output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
379			Remote:   fetchTarget,
380			RefSpecs: []string{refSpec},
381			NoTags:   true,
382		}); fetchErr != nil {
383			return fmt.Errorf("fetch failed: %s", output)
384		}
385	
386		repo, err := OpenRepository(ctx)
387		if err != nil {
388			return fmt.Errorf("failed to open git repository: %w", err)
389		}
390	
391		// Reconcile disconnected metadata branches before rebasing.
392		// The fetch above updated the remote-tracking ref, so reconciliation
393		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
394		// this cherry-picks local commits onto remote tip, updating the local ref.
395		// If reconciliation fails, abort — proceeding to rebase on disconnected
396		// branches would silently combine unrelated histories.
397		if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
398			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
399		}
400	
401		// Get local branch (re-read after potential reconciliation update)
402		localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
403		if err != nil {
404			return fmt.Errorf("failed to get local ref: %w", err)
405		}
406	
407		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
408		remoteRef, err := repo.Reference(fetchedRefName, true)
409		if err != nil {
410			return fmt.Errorf("failed to get remote ref: %w", err)
411		}
412	
413		// If local is already at or behind remote, fast-forward
414		if localRef.Hash() == remoteRef.Hash() {
415			return nil
416		}
417	
418		// Find merge base
419		repoPath, err := getRepoPath(repo)
420		if err != nil {
421			return fmt.Errorf("failed to get repo path: %w", err)
422		}
423		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
424		if err != nil {
425			return fmt.Errorf("failed to find merge base: %w", err)
426		}
427	
428		// If local is ancestor of remote (merge base == local), fast-forward to remote
429		if mergeBase == localRef.Hash() {
430			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
431			if err := repo.Storer.SetReference(ref); err != nil {
432				return fmt.Errorf("failed to fast-forward branch ref: %w", err)
433			}
434			if usedTempRef {
435				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
436			}
437			return nil
438		}
439	
440		// Collect commits reachable from local but not from remote and cherry-pick
441		// them onto the remote tip. This preserves local-only commits even when the
442		// local metadata branch already contains old merge commits, while avoiding
443		// replaying shared ancestors older than the true merge-base.
444		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
445		if err != nil {
446			return fmt.Errorf("failed to collect local commits: %w", err)
447		}
448	
449		if len(localCommits) == 0 {
450			// No local-only commits — just point to remote
451			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
452			if err := repo.Storer.SetReference(ref); err != nil {
453				return fmt.Errorf("failed to update branch ref: %w", err)
454			}
455			if usedTempRef {
456				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
457			}
458			return nil
459		}
460	
461		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits)
462		if err != nil {
463			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
464		}
465	
466		// Update branch ref
467		newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
468		if err := repo.Storer.SetReference(newRef); err != nil {
469			return fmt.Errorf("failed to update branch ref: %w", err)
470		}
471	
472		// Clean up temp ref if we used one (best-effort, not critical if it fails)
473		if usedTempRef {
474			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
475		}
476	
477		return nil
478	}
479	
480	// getMergeBase returns the merge base hash of two commits, or an error if they
481	// have no common ancestor.
482	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
483		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
484		defer cancel()
485	
486		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
487		cmd.Dir = repoPath
488		output, err := cmd.Output()
489		if err != nil {
490			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
491		}
492	
493		return plumbing.NewHash(strings.TrimSpace(string(output))), nil
494	}
495	
496	// collectCommitsSince returns non-merge commits reachable from tip but not from
497	// exclude, ordered oldest-first in topological order.
498	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
499		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
500		defer cancel()
501	
502		// cherryPickOnto computes each commit's delta against its first parent, so
503		// replaying merge commits would incorrectly re-apply changes that arrived via
504		// non-first-parent history. Limit the replay set to non-merge commits.
505		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
506		cmd.Dir = repoPath
507		output, err := cmd.Output()
508		if err != nil {
509			return nil, fmt.Errorf("git rev-list failed: %w", err)
510		}
511	
512		lines := strings.Fields(string(output))
513		if len(lines) > MaxCommitTraversalDepth {
514			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
515		}
516	
517		commits := make([]*object.Commit, 0, len(lines))
518		for _, line := range lines {
519			hash := plumbing.NewHash(line)
520			commit, commitErr := repo.CommitObject(hash)
521			if commitErr != nil {
522				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
523			}
524			if len(commit.ParentHashes) > 1 {
525				continue
526			}
527			commits = append(commits, commit)
528		}
529	
530		return commits, nil
531	}
532	
533	// startProgressDots prints dots to w every second until the returned stop function
534	// is called. The stop function prints the given suffix and a newline.
535	func startProgressDots(w io.Writer) func(suffix string) {
536		done := make(chan struct{})
537		stopped := make(chan struct{})
538		go func() {
539			defer close(stopped)
540			ticker := time.NewTicker(time.Second)
541			defer ticker.Stop()
542			for {
543				select {
544				case <-done:
545					return
546				case <-ticker.C:
547					fmt.Fprint(w, ".")
548				}
549			}
550		}()
551		return func(suffix string) {
552			close(done)
553			<-stopped // Wait for goroutine to finish before writing suffix
554			fmt.Fprintln(w, suffix)
555		}
556	}
557	
558	// createMergeCommitCommon creates a merge commit with multiple parents.
559	func createMergeCommitCommon(ctx context.Context, repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
560		authorName, authorEmail := GetGitAuthorFromRepo(repo)
561		now := time.Now()
562		sig := object.Signature{
563			Name:  authorName,
564			Email: authorEmail,
565			When:  now,
566		}
567	
568		commit := &object.Commit{
569			TreeHash:     treeHash,
570			ParentHashes: parents,
571			Author:       sig,
572			Committer:    sig,
573			Message:      message,
574		}
575	
576		checkpoint.SignCommitBestEffort(ctx, commit)
577	
578		obj := repo.Storer.NewEncodedObject()
579		if err := commit.Encode(obj); err != nil {
580			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
581		}
582	
583		hash, err := repo.Storer.SetEncodedObject(obj)
584		if err != nil {
585			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
586		}
587	
588		return hash, nil
589	}
